package com.financecoach.service;
import com.financecoach.dto.*;import com.financecoach.entity.*;import com.financecoach.repository.*;import org.springframework.data.domain.Sort;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.time.temporal.TemporalAdjusters;import java.util.*;
@Service public class ReportService {private final TransactionRepository tx;private final BudgetService budgets;private final BudgetRepository budgetRepo;private final FinancialGoalRepository goals;private final SubscriptionRepository subs;public ReportService(TransactionRepository tx,BudgetService budgets,BudgetRepository budgetRepo,FinancialGoalRepository goals,SubscriptionRepository subs){this.tx=tx;this.budgets=budgets;this.budgetRepo=budgetRepo;this.goals=goals;this.subs=subs;}
 @Transactional(readOnly=true) public ReportDto monthly(Long uid,Integer month,Integer year){LocalDate now=LocalDate.now();int m=month==null?now.getMonthValue():month,y=year==null?now.getYear():year;LocalDate start=LocalDate.of(y,m,1),end=start.with(TemporalAdjusters.lastDayOfMonth());BigDecimal income=n(tx.sumAmountByUserIdAndTypeAndDateBetween(uid,TransactionType.INCOME,start,end)),expense=n(tx.sumAmountByUserIdAndTypeAndDateBetween(uid,TransactionType.EXPENSE,start,end)),net=income.subtract(expense);ReportDto r=new ReportDto();r.setMonth(m);r.setYear(y);r.setTotalIncome(income.setScale(2));r.setTotalExpenses(expense.setScale(2));r.setNetSavings(net.setScale(2));r.setSavingsRate(income.signum()==0?BigDecimal.ZERO:net.divide(income,4,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)).setScale(2,RoundingMode.HALF_UP));r.setTopSpendingCategories(categorySpending(uid,start,end,expense));r.setBudgetPerformance(budgets.list(uid,m,y));r.setGoalProgress(goals.findByUserId(uid,Sort.unsorted()).size()+" goals tracked");r.setRecurringPaymentSummary(subs.findByUserIdAndActive(uid,true,Sort.unsorted()).size()+" active subscriptions");LocalDate p=start.minusMonths(1),pe=p.with(TemporalAdjusters.lastDayOfMonth());BigDecimal prev=n(tx.sumAmountByUserIdAndTypeAndDateBetween(uid,TransactionType.EXPENSE,p,pe));r.setSpendingChange(expense.subtract(prev));return r;}
 private List<CategorySpendingDto> categorySpending(Long uid,LocalDate start,LocalDate end,BigDecimal total){List<CategorySpendingDto> out=new ArrayList<>();for(Object[] row:tx.findCategorySpendingSummary(uid,TransactionType.EXPENSE,start,end)){BigDecimal amount=(BigDecimal)row[1];double pct=total.signum()==0?0:amount.divide(total,4,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)).doubleValue();out.add(new CategorySpendingDto((String)row[0],amount.setScale(2,RoundingMode.HALF_UP),pct,((Number)row[2]).longValue()));}return out;} private BigDecimal n(BigDecimal v){return v==null?BigDecimal.ZERO:v;}}
